9	const SHUTDOWN_REFCOUNT_POLL_INTERVAL: Duration = Duration::from_millis(100);
10	
11	/// Shared router state for the minimal single-model OpenAI server.
12	pub struct AppState {
13	    /// All public model IDs served by this frontend. The first entry is the
14	    /// primary ID used in responses; all entries are valid in requests.
15	    served_model_names: Vec<String>,
16	    /// Shared chat facade used by all requests.
17	    pub chat: ChatLlm,
18	    /// Whether to log a summary line for each completed request.
19	    pub enable_log_requests: bool,
20	    /// Number of in-flight inference requests currently owned by this frontend.
21	    server_load: AtomicU64,
22	}
23	
24	impl AppState {
25	    /// Construct one application state instance.
26	    ///
27	    /// `served_model_names` must be non-empty; the first entry is the primary
28	    /// model ID returned in API responses.
29	    ///
30	    /// # Panics
31	    ///
32	    /// Panics if `served_model_names` is empty.
33	    pub fn new(served_model_names: Vec<String>, chat: ChatLlm) -> Self {
34	        assert!(
35	            !served_model_names.is_empty(),
36	            "served_model_names must not be empty"
37	        );
38	        Self {
39	            served_model_names,
40	            chat,
41	            enable_log_requests: false,
42	            server_load: AtomicU64::new(0),
43	        }
44	    }
45	
46	    /// Enable per-request completion logging.
47	    pub fn with_log_requests(mut self, enabled: bool) -> Self {
48	        self.enable_log_requests = enabled;
49	        self
50	    }
51	
52	    /// The primary model name echoed back in API responses (the first served
53	    /// name).
54	    pub fn primary_model_name(&self) -> &str {
55	        self.served_model_names.first().map(String::as_str).unwrap_or_default()
56	    }
57	
58	    /// All model names served by this frontend.
59	    pub fn served_model_names(&self) -> &[String] {
60	        &self.served_model_names
61	    }
62	
63	    /// Return a reference to the underlying engine core client for utility
64	    /// calls.
65	    pub(crate) fn engine_core_client(&self) -> &EngineCoreClient {
66	        self.chat.engine_core_client()
67	    }
68	
69	    /// Return the current in-flight inference request count for the `/load`
70	    /// endpoint.
71	    pub fn server_load(&self) -> u64 {
72	        self.server_load.load(Ordering::Relaxed)
73	    }
74	
75	    /// Increment the in-flight inference request count, called by the load
76	    /// tracking middleware.
77	    pub(crate) fn increment_server_load(&self) {
78	        self.server_load.fetch_add(1, Ordering::Relaxed);
79	    }
80	
81	    /// Decrement the in-flight inference request count, called by the load
82	    /// tracking middleware.
83	    pub(crate) fn decrement_server_load(&self) {
84	        self.server_load.fetch_sub(1, Ordering::Relaxed);
85	    }
86	
87	    /// Wait until all request-owned references are dropped, then shut down the
88	    /// engine client.
89	    ///
90	    /// If the deadline elapses while request/connection tasks still hold state
91	    /// references, skip the clean engine-client shutdown and let process
92	    /// teardown reclaim the remaining resources.
93	    pub async fn shutdown(mut self: Arc<Self>, deadline: Instant) -> anyhow::Result<()> {
94	        loop {
95	            match Arc::try_unwrap(self) {
96	                Ok(state) => {
97	                    state.chat.shutdown().await?;
98	                    return Ok(());
99	                }
100	                Err(state) => self = state,
101	            }
102	            let ref_count = Arc::strong_count(&self);
103	
104	            let now = Instant::now();
105	            if now >= deadline {
106	                warn!(
107	                    ref_count,
108	                    "shutdown deadline elapsed before app state became idle; skipping engine-client shutdown"
109	                );
110	                return Ok(());
111	            }
112	
113	            sleep_until(std::cmp::min(
114	                deadline,
115	                now + SHUTDOWN_REFCOUNT_POLL_INTERVAL,
116	            ))
117	            .await;
118	        }
119	    }
120	}
