34	/// Build the shared application state for one configured model and one engine
35	/// client.
36	async fn build_state(config: &Config) -> Result<Arc<AppState>> {
37	    // Load both backends from the same model metadata so they stay in sync.
38	    let loaded = load_model_backends(
39	        &config.model,
40	        LoadModelBackendsOptions {
41	            renderer: config.renderer,
42	            chat_template: config.chat_template.clone(),
43	            chat_template_content_format: config.chat_template_content_format,
44	            default_chat_template_kwargs: config
45	                .default_chat_template_kwargs
46	                .clone()
47	                .unwrap_or_default(),
48	        },
49	    )
50	    .await
51	    .context("failed to create chat/text backends")?;
52	    let text_backend = loaded.text_backend;
53	    let chat_backend = loaded.chat_backend;
54	
55	    let coordinator_mode = config.effective_coordinator_mode(text_backend.is_moe());
56	    info!(
57	        engine_count = config.engine_count(),
58	        model_is_moe = text_backend.is_moe(),
59	        ?coordinator_mode,
60	        "resolved coordinator mode"
61	    );
62	
63	    let client = EngineCoreClient::connect(EngineCoreClientConfig {
64	        transport_mode: config.transport_mode.clone(),
65	        coordinator_mode,
66	        model_name: config.model.clone(),
67	        client_index: 0,
68	    })
69	    .await
70	    .context("failed to connect to engine core")?;
71	
72	    let llm = Llm::new(client).with_log_stats(!config.disable_log_stats);
73	    let text = TextLlm::new(llm, text_backend);
74	
75	    let chat = ChatLlm::new(text, chat_backend)
76	        .with_tool_call_parser(config.tool_call_parser.clone())
77	        .with_reasoning_parser(config.reasoning_parser.clone());
78	
79	    // If no served names are specified, fall back to the backend model path so
80	    // that the API always has at least one valid model ID.
81	    let served_model_names = if config.served_model_name.is_empty() {
82	        vec![config.model.clone()]
83	    } else {
84	        config.served_model_name.clone()
85	    };
86	
87	    Ok(Arc::new(
88	        AppState::new(served_model_names, chat).with_log_requests(config.enable_log_requests),
89	    ))
90	}
