18	const TRACKED_HANDLERS: &[&str] = &[
19	    "/v1/responses",
20	    "/v1/responses/{response_id}",
21	    "/v1/responses/{response_id}/cancel",
22	    "/v1/messages",
23	    "/v1/messages/count_tokens",
