70	/// A guard that decrements the server load when dropped.
71	struct ServerLoadGuard {
72	    state: Weak<AppState>,
73	}
74	
75	impl Drop for ServerLoadGuard {
76	    fn drop(&mut self) {
77	        if let Some(state) = self.state.upgrade() {
78	            state.decrement_server_load();
79	        }
80	    }
81	}
82	
83	/// A wrapper around response bodies that tracks server load by holding a
84	/// `ServerLoadGuard`, which will decrement the load when the body is fully
85	/// consumed and dropped.
86	struct LoadTrackedBody {
87	    inner: Body,
88	    _guard: ServerLoadGuard,
89	}
90	
91	// Simply delegate all `HttpBody` methods to the inner body.
92	impl HttpBody for LoadTrackedBody {
93	    type Data = Bytes;
94	    type Error = axum::Error;
95	
96	    fn poll_frame(
97	        mut self: Pin<&mut Self>,
98	        cx: &mut Context<'_>,
99	    ) -> Poll<Option<Result<Frame<Self::Data>, Self::Error>>> {
100	        Pin::new(&mut self.inner).poll_frame(cx)
