use axum::extract::{Request, State};
use axum::http::HeaderValue;
use axum::http::header::HeaderName;
use axum::middleware::Next;
use axum::response::Response;
use uuid::Uuid;

use crate::state::AppState;

/// Canonical (lowercase) name for the request-tracking response header.
static X_REQUEST_ID: HeaderName = HeaderName::from_static("x-request-id");

/// Attach an `x-request-id` header to responses when the feature is enabled.
///
/// When enabled, the value echoes an incoming `X-Request-Id` request header if
/// one is present, or a freshly generated UUID v4 (32 hex digits) otherwise.
/// When disabled, responses are passed through unchanged.
pub async fn attach_request_id(
    State(state): State<Arc<AppState>>,
    req: Request,
    next: Next,
) -> Response {
    if !state.enable_request_id_headers {
        return next.run(req).await;
    }

    // Reuse the incoming request ID when valid, otherwise mint a new UUID v4.
    let request_id = req
        .headers()
        .get(&X_REQUEST_ID)
        .cloned()
        .unwrap_or_else(|| {
            HeaderValue::from_str(&Uuid::new_v4().simple().to_string())
                .expect("hex UUID is a valid header value")
        });

    let mut response = next.run(req).await;
    response.headers_mut().insert(X_REQUEST_ID.clone(), request_id);
    response
}
